                        <InputGroupInput
                          aria-invalid={Boolean(
                            errors.workspaceEmail ||
                            (state.request.workspaceEmailTaken && !emailEdited),
                          )}
                          defaultValue={state.request.workspaceEmail.replace(/@.*$/, "")}
                          id="workspace-email"
                          key={state.request.workspaceEmail}
                          name="workspaceEmail"
                          onChange={() => setEmailEdited(true)}
                        />
