                    </Field>
                  </FieldGroup>
                </FieldSet>
                <div className="mt-5 flex flex-wrap gap-2">
                  {editing ? (
                    <Button
                      disabled={pending || planState.status !== "ready"}
                      type="submit"
                      variant="outline"
                    >
                      {pending && <Spinner data-icon="inline-start" />}
                      <PencilIcon data-icon="inline-start" /> Done
