            </dl>
            {acceptError && (
              <p className="text-sm text-destructive" role="alert">
                {acceptError}
              </p>
            )}
            <AlertDialogFooter>
              <AlertDialogCancel disabled={pending}>Cancel</AlertDialogCancel>
              <AlertDialogAction disabled={pending} onClick={() => void accept()}>
                {pending && <Spinner data-icon="inline-start" />}
                Confirm acceptance
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      )}
    </section>
  );
